package com.climbme.app.dashboard;import com.climbme.app.auth.UserAccount;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/dashboard") public class DashboardController{private final DashboardService service;public DashboardController(DashboardService service){this.service=service;}@GetMapping public DashboardResponse get(@AuthenticationPrincipal UserAccount user){return service.dashboard(user);}}
